// Helper functions for dynamic resolution:

/**
 * Returns all 31 days of the devotional
 */
export function getAllDevotionals() {
  return DEVOTIONAL_DAYS;
}

/**
 * Retrieves a devotional entry by day number (1 - 31).
 * Clamps to valid range or falls back to Day 1.
 */
export function getDevotionalByDay(dayNumber) {
  const num = parseInt(dayNumber, 10);
  if (isNaN(num)) return DEVOTIONAL_DAYS[0];
  const safeDay = Math.min(Math.max(num, 1), 31);
  return DEVOTIONAL_DAYS.find((d) => d.day === safeDay) || DEVOTIONAL_DAYS[0];
}

/**
 * Retrieves a devotional entry by its slug (e.g. 'day-01' or 'day-15')
 */
export function getDevotionalBySlug(slug) {
  if (!slug) return DEVOTIONAL_DAYS[0];
  const normalized = slug.toLowerCase().trim();
  const match = DEVOTIONAL_DAYS.find((d) => d.slug === normalized);
  if (match) return match;
  // If user passes '1' or 'day1'
  const digits = normalized.replace(/\D/g, '');
  if (digits) {
    return getDevotionalByDay(digits);
  }
  return DEVOTIONAL_DAYS[0];
}

/**
 * Dynamically resolves "today's" devotional.
 * Defaults to the current calendar day of the month (1-31),
 * ensuring the website is fresh and rotating automatically every single day!
 */
export function getTodayDevotional() {
  const today = new Date();
  const dayOfMonth = today.getDate(); // 1 - 31
  return getDevotionalByDay(dayOfMonth);
}

/**
 * Generates formatted WhatsApp text for sharing the apostolic decree to status or group chat
 */
export function formatWhatsAppShareText(devotional, siteUrl = 'https://christthepotterchurch.org') {
  const url = `${siteUrl}/devotional/${devotional.slug}`;
  return `*TODAY'S APOSTOLIC DECREE* 🕊️\n` +
    `*Christ The Potter Church*\n` +
    `*Setman:* Apostle Oluwafunminiyi Olufisayo\n\n` +
    `*Theme:* ${DEVOTIONAL_THEME}\n` +
    `*${devotional.dayFormatted}:* ${devotional.title}\n` +
    `*Anchor:* ${devotional.anchorScripture}\n\n` +
    `"${devotional.anchorVerse}"\n\n` +
    `*APOSTOLIC DECREE & PRAYER:*\n${devotional.prayer}\n\n` +
    `*Bible In A Year:* ${devotional.bibleInAYear}\n\n` +
    `📖 Read today's full devotional & download daily card:\n${url}`;
}

